# Review package: 8c27f3088f9346e86c0a60f9f2a6345730b5c1c5..HEAD

## Commits
f7873f9 Add greeting module with custom formatting

## Files changed
 greet.js      | 18 ++++++++++++++++++
 greet.test.js | 45 +++++++++++++++++++++++++++++++++++++++++++++
 2 files changed, 63 insertions(+)

## Diff
diff --git a/greet.js b/greet.js
new file mode 100644
index 0000000..4a90d6c
--- /dev/null
+++ b/greet.js
@@ -0,0 +1,18 @@
+function greet(name, options = {}) {
+  const { prefix = 'Hello', uppercase = false } = options;
+
+  // Handle empty input gracefully with a default
+  const displayName = (name === null || name === undefined || name === '')
+    ? 'friend'
+    : name;
+
+  let greeting = `${prefix}, ${displayName}!`;
+
+  if (uppercase) {
+    greeting = greeting.toUpperCase();
+  }
+
+  return greeting;
+}
+
+module.exports = { greet };
diff --git a/greet.test.js b/greet.test.js
new file mode 100644
index 0000000..677eb23
--- /dev/null
+++ b/greet.test.js
@@ -0,0 +1,45 @@
+const { describe, it } = require('node:test');
+const assert = require('node:assert');
+const { greet } = require('./greet');
+
+describe('greet', () => {
+  it('returns a greeting with the provided name', () => {
+    const result = greet('Alice');
+    assert.strictEqual(result, 'Hello, Alice!');
+  });
+
+  it('handles empty string gracefully', () => {
+    const result = greet('');
+    assert.strictEqual(result, 'Hello, friend!');
+  });
+
+  it('handles null gracefully', () => {
+    const result = greet(null);
+    assert.strictEqual(result, 'Hello, friend!');
+  });
+
+  it('handles undefined gracefully', () => {
+    const result = greet(undefined);
+    assert.strictEqual(result, 'Hello, friend!');
+  });
+
+  it('supports custom prefix', () => {
+    const result = greet('Bob', { prefix: 'Hi' });
+    assert.strictEqual(result, 'Hi, Bob!');
+  });
+
+  it('supports uppercase formatting', () => {
+    const result = greet('Charlie', { uppercase: true });
+    assert.strictEqual(result, 'HELLO, CHARLIE!');
+  });
+
+  it('supports both custom prefix and uppercase', () => {
+    const result = greet('Dave', { prefix: 'Welcome', uppercase: true });
+    assert.strictEqual(result, 'WELCOME, DAVE!');
+  });
+
+  it('applies uppercase to default friend greeting', () => {
+    const result = greet('', { uppercase: true });
+    assert.strictEqual(result, 'HELLO, FRIEND!');
+  });
+});
